int run(int argc,wchar_t** argv){check(argc==2,"oracle path");std::ifstream input(std::filesystem::path(argv[1]),std::ios::binary);const std::string bytes{std::istreambuf_iterator<char>(input),{}};const auto oracle=JsonObject::Parse(winrt::to_hstring(bytes));const auto rows=oracle.GetNamedArray(L"cases"),linked=oracle.GetNamedArray(L"linked"),detections=oracle.GetNamedArray(L"detections");check(rows.Size()==882&&linked.Size()==24&&detections.Size()==32,"oracle coverage");unsigned aliases=0;for(unsigned i=0;i<rows.Size();++i){const auto row=rows.GetObjectAt(i);context=winrt::to_string(row.GetNamedString(L"name"));RasterHistoryFixture::run(row,false,i%83==0);if(i%53==0){RasterHistoryFixture::run(row,true);++aliases;}}for(auto v:linked){const auto row=v.GetObject();context=winrt::to_string(row.GetNamedString(L"name"));RasterHistoryFixture::run(row);}for(auto v:detections){const auto row=v.GetObject();context=winrt::to_string(row.GetNamedString(L"name"));RasterHistoryFixture::detect(row);}context="edges";RasterHistoryFixture::edges(rows.GetObjectAt(0));std::cout<<rows.Size()<<" actual legacy resize/snapshot histories, "<<linked.Size()<<" placed linked-layer cases, "<<aliases<<" frame aliases, "<<detections.Size()<<" actual legacy composite detections; direct/worker/raw history/cancel/stale/budget/encoders passed\n";return 0;}
int wmain(int argc,wchar_t** argv){const auto hr=RoInitialize(RO_INIT_MULTITHREADED);try{const auto result=run(argc,argv);if(hr==S_OK)winrt::clear_factory_cache();if(SUCCEEDED(hr))RoUninitialize();return result;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';if(hr==S_OK)winrt::clear_factory_cache();if(SUCCEEDED(hr))RoUninitialize();return 1;}}
